function load_table_data() {
  var Is_Publish = $("#Is_Publish").val();
  var Is_Unlimited = $("#Is_Unlimited").val();
  var filter_date = $("#filter_date").val();
  var frmDate = $("#frmDate").val();
  var toDate = $("#toDate").val();

  var dataurl = constvar.api_url + "nne_setup/nne_list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";
  var dtablelist = $("#myTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],

    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,

    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer" + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback
      });
    },
    oLanguage: {
      sEmptyTable: message
    },
    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0]
    }],

    aoColumns: [{ data: null }, { data: "category_typeid" }, { data: "title" }, { data: "image" }, { data: "startdate" }, { data: "enddate" }, { data: "is_publish" }, { data: "is_unlimited" }, { data: "action" }],

    fnServerParams: function fnServerParams(aoData) {
      aoData.push({ name: "Is_Publish", value: Is_Publish });
      aoData.push({ name: "Is_Unlimited", value: Is_Unlimited });
      aoData.push({ name: "filter_date", value: filter_date });
      aoData.push({ name: "frmDate", value: frmDate });
      aoData.push({ name: "toDate", value: toDate });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      $(nRow).attr("id", "listid_" + tblid);
    }
  }).columnFilter({
    sPlaceHolder: "head:after",
    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: null }, { type: "text" }, { type: "text" }, { type: null }, { type: null }, { type: null }]
  });
  $(document).off("click", "#searchByDate");
  $(document).on("click", "#searchByDate", function () {
    Is_Publish = $("#Is_Publish").val();
    Is_Unlimited = $("#Is_Unlimited").val();
    filter_date = $("#filter_date").val();
    frmDate = $("#frmDate").val();
    toDate = $("#toDate").val();
    dtablelist.fnDraw();
  });
}

