function load_table_data() {
  var date_type = $('#career_date').val();
  var gender_id = $("#job_gender").val();
  var start_date = $('#job_startdate').val();
  var end_date = $('#job_enddate').val();
  var search_text = $("#search_text").val();

  var dataurl = constvar.api_url + "career_list/list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";

  var dtablelist = $("#careerListTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],
    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,
    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback,
        error: function error(xhr, _error, code) {
          if (xhr.status == 401) {
            message = "Please reload the page";
          }
          console.log(_error, code);
        }
      });
    },
    oLanguage: {
      sEmptyTable: message
    },

    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0, 4, 5, 7, 8, 9, 10, 11, 12]
    }],

    aoColumns: [{ data: null }, { data: "jobcode" }, { data: "job_title" }, { data: "apply_before" }, { data: "no_of_vacancy" }, { data: "experience_type" }, { data: "start_date" },
    // { data: "end_date" },
    { data: "driving_license" }, { data: "salary_type" }, { data: "gender" }, { data: "apply_online" }, { data: "apply_direct" }, { data: "action" }],

    fnServerParams: function fnServerParams(aoData) {
      aoData.push({ name: "date_type", value: date_type });
      aoData.push({ name: "start_date", value: start_date });
      aoData.push({ name: "end_date", value: end_date });
      aoData.push({ name: "gender_id", value: gender_id });
      aoData.push({ name: "search_text", value: search_text });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var cur_status = aData.curstatus;
      // console.log('T'+cur_status);
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      $(nRow).attr("id", "listid_" + tblid);
      if (cur_status == "N") {
        $(nRow).attr("style", "background:#f98280  !important");
      } else {
        $(nRow).attr("style", "background:#b7e8b9 !important");
      }
    }
  }).columnFilter({
    sPlaceHolder: "head:after",

    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: "text" }, { type: null }, { type: null }, { type: "text" },
    // { type: "text" },
    { type: null }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }]
  });

  $(document).off("keyup", "#search_text");
  $(document).on("keyup", "#search_text", function () {
    date_type = $('#career_date').val();
    gender_id = $('#job_gender').val();
    start_date = $('#job_startdate').val();
    end_date = $('#job_enddate').val();
    search_text = $("#search_text").val();
    dtablelist.fnDraw();
  });

  $(document).off("click", "#searchEmployeeList");
  $(document).on("click", "#searchEmployeeList", function () {
    date_type = $('#career_date').val();
    gender_id = $('#job_gender').val();
    start_date = $('#job_startdate').val();
    end_date = $('#job_enddate').val();
    search_text = $("#search_text").val();
    dtablelist.fnDraw();
  });

  $(document).off("click", "#publish_job");
  $(document).on("click", "#publish_job", function (e) {
    var id = $(this).data('id');
    var answer = window.confirm('Are you sure?');
    if (answer) {
      var url = constvar.api_url + "career_list/publish_job";
      axios.post(url, { id: id }).then(function (response) {
        if (response.data.status == "success") {
          alert('Operation Successful');
          dtablelist.fnDraw();
        } else {
          alert('Error! Operation unsucessful');
        }
      });
    }
    console.log(id);
    // console.log('test');
  });

  // $(document).off("click", "#edit_job");
  // $(document).on("click", "#edit_job", function(e){
  //   let id = $(this).data('id');
  //   let url =  "badministrator/career_setup?id=" + id;
  //   // console.log(id);
  //   axios
  //     .get(url, {id:id})
  //     .then((response) => {
  //       // if
  //     });

  // });
}

$(document).off('change', '#career_date');
$(document).on('change', '#career_date', function (e) {
  var value = $(this).val();
  if (value == "R") {
    $('.range_div').show(500);
  } else {
    $('.range_div').hide(500);
  }
});

