function load_table_data() {
  var category = $("#category").val();

  var dataurl = constvar.api_url + "technology_description/technologydescription_list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";
  var dtablelist = $("#myTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],

    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,

    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer" + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback
      });
    },
    oLanguage: {
      sEmptyTable: message
    },
    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0]
    }],

    aoColumns: [{ data: null }, { data: "technology_catid" }, { data: "title" }, { data: "icon" }, { data: "image" }, { data: "order" }, { data: "is_publish" }, { data: "action" }],

    fnServerParams: function fnServerParams(aoData) {
      // aoData.push({ name: "frmDate", value: frmDate });

      aoData.push({ name: "category", value: category });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      $(nRow).attr("id", "listid_" + tblid);
    }
  }).columnFilter({
    sPlaceHolder: "head:after",
    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }]
  });

  $(document).off("change", "#searchBypage");
  $(document).on("change", "#searchBypage", function () {
    category = $("#category").val();

    dtablelist.fnDraw();
  });
}

