$(document).off("click", ".order_list");
$(document).on("click", ".order_list", function (e) {
  if (this.checked) {
    $(".ordered").each(function () {
      this.checked = true;
      $("#order_approve").show();
      $("#order_cancel").show();
    });
  } else {
    $(".ordered").each(function () {
      this.checked = false;
      $("#order_approve").hide();
      $("#order_cancel").hide();
    });
  }
});

$(document).off("click", "#order_approve,#order_cancel");
$(document).on("click", "#order_approve,#order_cancel", function (e) {
  var action = e.target.id;
  var message = "";
  var status = "";
  if (action == "order_approve") {
    message = "Confirm These Order ?";
    status = "CO";
  } else if (action == "order_cancel") {
    message = "Cancel These Order ?";
    status = "C";
  }

  var conf = confirm(message);
  if (conf) {
    var ch_id = [];
    $.each($("input[name='checkout_id[]']:checked"), function () {
      ch_id.push($(this).val());
    });
    var url = constvar.api_url + "product_order/change_order_status";
    axios.post(url, { ch_id: ch_id, status: status }).then(function (response) {
      if (response.data.status == "success") {
        $("#searchByDate").click();
      } else {
        $("#searchByDate").click();
      }
    });
  }
});

$(document).off("click", ".ordered");
$(document).on("click", ".ordered", function (e) {
  if (this.checked) {
    this.checked = true;
    $("#order_approve").show();
    $("#order_cancel").show();
  } else {
    var check = $(".ordered:checkbox").filter(":checked");
    this.checked = false;
    if (check.length >= 1) {
      $("#order_approve").show();
      $("#order_cancel").show();
    } else {
      $("#order_approve").hide();
      $("#order_cancel").hide();
    }
  }
});

