function search_delivery_status(date_range, from_date, to_date, payment_method, delivery_status) {
  var url = constvar.api_url + "deliver_order/get_delivery_status";
  axios.post(url, {
    frmDate: from_date,
    toDate: to_date,
    date_range: date_range,
    payment_method: payment_method,
    delivery_status: delivery_status
  }).then(function (response) {
    if (response.data.status == "success") {
      $("#pending").html(response.data.pendingcnt);
      $("#delivered").html(response.data.deliveredcnt);
    } else {
      $("#pending").html("0");
      $("#delivered").html("0");
    }
  });
}

function load_table_data() {
  $(".delivery_list").removeClass("form-check-input");
  var date_range = $("#date_range").val();
  var payment_method = $("#payment_method").val();
  var from_date = $("#from_date").val();
  var to_date = $("#to_date").val();
  var delivery_status = $("#delivery_status").val();

  var dataurl = constvar.api_url + "deliver_order/delivery_list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";
  search_delivery_status(date_range, from_date, to_date, payment_method, delivery_status);
  var dtablelist = $("#myTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],

    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,

    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback
      });
    },
    oLanguage: {
      sEmptyTable: message
    },
    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0]
    }],

    aoColumns: [{ data: null }, { data: "date" }, { data: "customer_name" }, { data: "mobile_no" }, { data: "orderno" }, { data: "total_items" }, { data: "payment_method" }, { data: "currency" }, { data: "grand_total" }, { data: "shipping_address" }, { data: "status" }, { data: "delivery_assign" }, { data: "assign_user" }, { data: "action" }],

    fnServerParams: function fnServerParams(aoData) {
      aoData.push({ name: "date_range", value: date_range });
      aoData.push({ name: "frmDate", value: from_date });
      aoData.push({ name: "toDate", value: to_date });
      aoData.push({ name: "payment_method", value: payment_method });
      aoData.push({ name: "delivery_status", value: delivery_status });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var id = aData.id;
      var status = aData.delivery_assign;
      if (status == "No") {
        $("td:first", nRow).html('<input type="checkbox" class="delivery_item" name="checkout_id[]" value=' + id + ">");
      } else {
        $("td:first", nRow).html("");
      }
      // $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      var st_style = aData.st_style;
      $(nRow).attr("id", "listid_" + tblid);
      $(nRow).attr("style", st_style);
    }
  }).columnFilter({
    sPlaceHolder: "head:after",
    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }, { type: null }]
  });
  $(document).off("click", "#searchDeliveryList");
  $(document).on("click", "#searchDeliveryList", function () {
    date_range = $("#date_range").val();
    payment_method = $("#payment_method").val();
    delivery_status = $("#delivery_status").val();
    from_date = $("#from_date").val();
    to_date = $("#to_date").val();
    dtablelist.fnDraw();
    search_delivery_status(date_range, from_date, to_date, payment_method, delivery_status);
  });
}

$(document).off("click", ".delivery_list");
$(document).on("click", ".delivery_list", function (e) {
  if (this.checked) {
    $(".delivery_item").each(function () {
      this.checked = true;
      $("#assign_deliver").show();
      $("#assign_form").show();
    });
  } else {
    $(".delivery_item").each(function () {
      this.checked = false;
      $("#assign_deliver").hide();
      $("#assign_form").hide();
    });
  }
});

$(document).off("click", "#assign_deliver");
$(document).on("click", "#assign_deliver", function (e) {
  var assign_userid = $("#assign_userid").val();
  if (assign_userid == null || assign_userid == undefined || assign_userid == "") {
    $("#assign_userid").focus();
    return false;
  }
  var conf = confirm("Assign Delivery ?");
  if (conf) {
    var ch_id = [];
    $.each($("input[name='checkout_id[]']:checked"), function () {
      ch_id.push($(this).val());
    });

    var url = constvar.api_url + "deliver_order/assign_user_to_deliver_order";
    axios.post(url, { ch_id: ch_id, assign_userid: assign_userid }).then(function (response) {
      if (response.data.status == "success") {
        $("#searchDeliveryList").click();
      } else {
        $("#searchDeliveryList").click();
      }
    });
  }
});

$(document).off("click", ".delivery_item");
$(document).on("click", ".delivery_item", function (e) {
  if (this.checked) {
    this.checked = true;
    $("#assign_deliver").show();
    $("#assign_form").show();
  } else {
    var check = $(".delivery_item:checkbox").filter(":checked");
    this.checked = false;
    if (check.length >= 1) {
      $("#assign_deliver").show();
      $("#assign_form").show();
    } else {
      $("#assign_deliver").hide();
      $("#assign_form").hide();
    }
  }
});

$(document).off("click", ".deliver_stat_id");
$(document).on("click", ".deliver_stat_id", function (e) {
  if (this.checked) {
    this.checked = true;
    $("#delivery_completed").show();
  } else {
    var check = $(".deliver_stat_id:checkbox").filter(":checked");
    this.checked = false;
    if (check.length >= 1) {
      $("#delivery_completed").show();
    } else {
      $("#delivery_completed").hide();
    }
  }
});

$(document).off("click", "#delivery_completed");
$(document).on("click", "#delivery_completed", function (e) {
  var conf = confirm("Change Delivery Status ?");
  if (conf) {
    var del_id = [];
    $.each($("input[name='deliver_id[]']:checked"), function () {
      del_id.push($(this).val());
    });

    var url = constvar.api_url + "deliver_order/change_delivery_status_completed";
    axios.post(url, { del_id: del_id }).then(function (response) {
      if (response.data.status == "success") {
        $("#searchDeliveryList").click();
      } else {
        $("#searchDeliveryList").click();
      }
    });
  }
});

