function load_table_data() {
  var location_id = $("#location_id").val();
  var department_id = $("#department_id").val();
  var designation_id = $("#designation_id").val();
  var employee_id = $("#employee_id").val();
  var gender_id = $("#gender_id").val();
  var employee_type_id = $("#employee_type_id").val();
  var search_text = $("#search_text").val();
  var page_orientation = $("#page_orientation").val();
  var emp_status = $("#emp_status").val();

  var dataurl = constvar.api_url + "employee/datatable_list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";

  var dtablelist = $("#employeeTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],
    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,
    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback,
        error: function error(xhr, _error, code) {
          if (xhr.status == 401) {
            message = "Please reload the page";
          }
          console.log(_error, code);
        }
      });
    },
    oLanguage: {
      sEmptyTable: message
    },

    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0, 9]
    }],

    aoColumns: [{ data: null }, { data: "empcode" }, { data: "full_name" }, { data: "gend_name" }, { data: "depname" }, { data: "designation_name" }, { data: "mobile" }, { data: "email" }, { data: "status" }, { data: "action" }],

    fnServerParams: function fnServerParams(aoData) {
      aoData.push({ name: "location_id", value: location_id });
      aoData.push({ name: "department_id", value: department_id });
      aoData.push({ name: "designation_id", value: designation_id });
      aoData.push({ name: "employee_id", value: employee_id });
      aoData.push({ name: "gender_id", value: gender_id });
      aoData.push({ name: "employee_type_id", value: employee_type_id });
      aoData.push({ name: "search_text", value: search_text });
      aoData.push({ name: "page_orientation", value: page_orientation });
      aoData.push({ name: "emp_status", value: emp_status });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var cur_status = aData.cstatus;
      // console.log('T'+cur_status);
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      $(nRow).attr("id", "listid_" + tblid);
      if (cur_status == "N") {
        $(nRow).attr("style", "background:#f98280  !important");
      } else {
        $(nRow).attr("style", "background:#b7e8b9 !important");
      }
    }
  }).columnFilter({
    sPlaceHolder: "head:after",

    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: null }]
  });

  $(document).off("keyup", "#search_text");
  $(document).on("keyup", "#search_text", function () {
    location_id = $("#location_id").val();
    department_id = $("#department_id").val();
    designation_id = $("#designation_id").val();
    employee_id = $("#employee_id").val();
    gender_id = $("#gender_id").val();
    employee_type_id = $("#employee_type_id").val();
    emp_status = $("#emp_status").val();
    search_text = $("#search_text").val();
    dtablelist.fnDraw();
  });

  $(document).off("click", "#searchEmployeeList");
  $(document).on("click", "#searchEmployeeList", function () {
    location_id = $("#location_id").val();
    department_id = $("#department_id").val();
    designation_id = $("#designation_id").val();
    employee_id = $("#employee_id").val();
    gender_id = $("#gender_id").val();
    employee_type_id = $("#employee_type_id").val();
    search_text = $("#search_text").val();
    emp_status = $("#emp_status").val();
    dtablelist.fnDraw();
  });

  $(document).off("click", "#emp_resgn_btn");
  $(document).on("click", "#emp_resgn_btn", function (e) {
    var id = $(this).data("id");
    var answer = window.confirm("Resign this employee?");
    if (answer) {
      var url = constvar.api_url + "employee/resign";
      axios.post(url, { id: id }).then(function (res) {
        if (res.data.status == "success") {
          alert("Resignation successful for this employee");
          dtablelist.fnDraw();
        } else {
          alert("Error!");
        }
      });
    }
  });
}

$(document).off("change", "#location_id");
$(document).on("change", "#location_id", function () {
  var locationid = $(this).val();
  var option = "<option value=''>--All--</option>";
  axios.post(constvar.api_url + "general_data/get_employee", { locationid: locationid }).then(function (response) {
    if (response.data.status == "success") {
      var employee_list = response.data.employee_list;
      $.each(employee_list, function (key, value) {
        option += "<option value=\"" + value.id + "\">" + value.full_name + "</option>";
      });
      $("#employee_id").html(option);
    } else {
      $("#employee_id").html(option);
    }
  });
});

