function load_table_data() {
  var location_id = $("#location").val();
  var department_id = $("#department").val();
  var designation_id = $("#designation").val();
  var employee_id = $("#employee").val();
  var date_type = $("#date_type").val();
  var fromdate = $("#fromdate").val();
  var todate = $("#todate").val();
  var page_orientation = $("#page_orientation").val();

  var dataurl = constvar.api_url + "roster/employee_roster_list";
  var message = "";
  message = "<p class='text-danger'>No Record Found!! </p>";

  var dtablelist = $("#rosterListTable").dataTable({
    sPaginationType: "full_numbers",
    bSearchable: false,
    lengthMenu: [[15, 30, 45, 60, 100, 200, 500, -1], [15, 30, 45, 60, 100, 200, 500, "All"]],
    iDisplayLength: 10,
    sDom: "ltipr",
    bAutoWidth: false,
    autoWidth: true,
    aaSorting: [[0, "desc"]],
    bProcessing: true,
    bServerSide: true,
    sAjaxSource: dataurl,
    fnServerData: function fnServerData(sSource, aoData, fnCallback) {
      $.ajax({
        dataType: "json",
        type: "GET",
        headers: {
          Authorization: "Bearer " + localStorage.getItem("backend-jwt-token")
        },
        url: sSource,
        data: aoData,
        success: fnCallback,
        error: function error(xhr, _error, code) {
          if (xhr.status == 401) {
            message = "Please reload the page";
          }
          console.log(_error, code);
        }
      });
    },
    oLanguage: {
      sEmptyTable: message
    },

    aoColumnDefs: [{
      bSortable: false,
      aTargets: [0]
    }],

    aoColumns: [{ data: null }, { data: "refno" }, { data: "type" }, { data: "empcode" }, { data: "full_name" }, { data: "department" }, { data: "designation" }, { data: "start_date" }, { data: "start_time" }, { data: "end_date" }, { data: "end_time" }, { data: "duration" }, { data: "place" }, { data: "remarks" }, { data: "status" }, { data: "checkin" }, { data: "checkout" }, { data: "work_details" }],

    fnServerParams: function fnServerParams(aoData) {
      aoData.push({ name: "location_id", value: location_id });
      aoData.push({ name: "department_id", value: department_id });
      aoData.push({ name: "designation_id", value: designation_id });
      aoData.push({ name: "employee_id", value: employee_id });
      aoData.push({ name: "date_type", value: date_type });
      aoData.push({ name: "from_date", value: fromdate });
      aoData.push({ name: "to_date", value: todate });
      aoData.push({ name: "page_orientation", value: page_orientation });
    },

    fnRowCallback: function fnRowCallback(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var id = aData.id;
      $("td:first", nRow).html("<input type=\"checkbox\" name=\"shift_detail_id[]\" class=\"shift_ids\" value=\"" + id + "\"></input>");
      // $("td:first", nRow).html(oSettings._iDisplayStart + iDisplayIndex + 1);
      return nRow;
    },

    fnCreatedRow: function fnCreatedRow(nRow, aData, iDisplayIndex) {
      var oSettings = dtablelist.fnSettings();
      var status_color = aData.status_color;
      var tblid = oSettings._iDisplayStart + iDisplayIndex + 1;
      $(nRow).attr("id", "listid_" + tblid);
      $(nRow).attr("style", "background:" + status_color + " !important");
    }
  }).columnFilter({
    sPlaceHolder: "head:after",

    aoColumns: [{ type: null }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: "text" }, { type: null }, { type: null }, { type: null }, { type: null }]
  });

  $(document).off("click", "#searchEmployeeRoster");
  $(document).on("click", "#searchEmployeeRoster", function () {
    location_id = $("#location").val();
    department_id = $("#department").val();
    designation_id = $("#designation").val();
    employee_id = $("#employee").val();
    date_type = $("#date_type").val();
    fromdate = $("#fromdate").val();
    todate = $("#todate").val();
    page_orientation = $("#page_orientation").val();
    dtablelist.fnDraw();
  });
}

$(document).off("change", "#date_type");
$(document).on("change", "#date_type", function (e) {
  var value = $(this).val();
  if (value == "range") {
    $(".roster_rangediv").show(500);
  } else {
    $(".roster_rangediv").hide(500);
  }
});

$(document).off("click", "#selectAll");
$(document).on("click", "#selectAll", function (e) {
  if (this.checked) {
    $(".shift_ids").each(function () {
      this.checked = true;
      $("#rosterStatusDiv").show();
    });
  } else {
    $(".shift_ids").each(function () {
      this.checked = false;
      $("#rosterStatusDiv").hide();
    });
  }
});

$(document).off("click", ".shift_ids");
$(document).on("click", ".shift_ids", function (e) {
  if (this.checked) {
    this.checked = true;
    $("#rosterStatusDiv").show();
  } else {
    var check = $(".shift_ids:checkbox").filter(":checked");
    this.checked = false;
    if (check.length >= 1) {
      $("#rosterStatusDiv").show();
    } else {
      $("#rosterStatusDiv").hide();
    }
  }
});

$(document).off("click", "#saveStatus");
$(document).on("click", "#saveStatus", function (e) {
  var conf = confirm("Change Status? ");
  if (conf) {
    var shift_detail_ids = [];
    $.each($("input[name='shift_detail_id[]']:checked"), function () {
      shift_detail_ids.push($(this).val());
    });
    var status_id = $("#roster_status").val();
    var url = constvar.api_url + "roster/change_status";
    axios.post(url, { shift_detail_ids: shift_detail_ids, status_id: status_id }).then(function (response) {
      $("#searchEmployeeRoster").trigger("click");
    });
    $("#rosterStatusDiv").hide();
    $("#selectAll").removeAttr("checked");
  }
});

